package service

import (
	"context"
	"errors"
	"fmt"
	"net/url"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
)

// Query business errors, both recognizable with errors.Is.
var (
	// ErrInvalidPlacementQuery is returned when the parameter set is not one
	// of the documented combinations. Validation happens before any storage
	// access, so an invalid query never reaches the store.
	ErrInvalidPlacementQuery = errors.New("invalid placement query")
	// ErrPlacementNotFound is returned by the single-record form when the
	// (namespace, name) identity is unknown.
	ErrPlacementNotFound = errors.New("placement not found")
)

// QueryResult carries the outcome of Query. Exactly one field is non-nil on
// success: Record for the single-record form, Items for the list form. On
// failure both are nil. Items is never nil on a successful list, even when
// nothing matched.
type QueryResult struct {
	Record *store.Placement
	Items  []*store.Placement
}

// Query is the transport-independent read entry point. values holds the
// already-decoded query parameters with duplicates preserved; it is only
// read, never modified, and its values are matched exactly as given — no
// trimming and no further decoding.
//
// Only the four documented keys are accepted. With name, namespace is the
// only other allowed key and the result is the single stored record or
// ErrPlacementNotFound. Without name, namespace, queue and node intersect as
// filters, omitted conditions are ignored, and a nil or empty set lists
// everything. Lists are ordered by namespace then name in UTF-8 byte order;
// a node filter never matches a rejected record. Unknown keys, repeated or
// empty values and illegal combinations yield ErrInvalidPlacementQuery, and
// any persistence failure yields ErrStorageUnavailable.
func (s *Service) Query(ctx context.Context, values url.Values) (QueryResult, error) {
	params, err := validateQuery(values)
	if err != nil {
		return QueryResult{}, err
	}

	if name, hasName := params["name"]; hasName {
		rec, err := s.st.Get(ctx, params["namespace"], name)
		if errors.Is(err, store.ErrNotFound) {
			return QueryResult{}, fmt.Errorf("query placement: %w", ErrPlacementNotFound)
		}
		if err != nil {
			return QueryResult{}, queryStorageError(err)
		}
		return QueryResult{Record: rec}, nil
	}

	recs, err := s.st.List(ctx, store.ListFilter{
		Namespace: params["namespace"],
		Queue:     params["queue"],
		Node:      params["node"],
	})
	if err != nil {
		return QueryResult{}, queryStorageError(err)
	}
	if recs == nil {
		recs = []*store.Placement{}
	}
	return QueryResult{Items: recs}, nil
}

var allowedQueryKeys = map[string]bool{
	"namespace": true,
	"name":      true,
	"queue":     true,
	"node":      true,
}

// validateQuery accepts only the four documented keys, each exactly once with
// a non-empty value, and only the documented combinations: name requires
// namespace and forbids queue and node.
func validateQuery(values url.Values) (map[string]string, error) {
	params := make(map[string]string, len(values))
	for key, vals := range values {
		if !allowedQueryKeys[key] || len(vals) != 1 || vals[0] == "" {
			return nil, fmt.Errorf("query placement: %w", ErrInvalidPlacementQuery)
		}
		params[key] = vals[0]
	}
	if _, hasName := params["name"]; hasName {
		_, hasNamespace := params["namespace"]
		_, hasQueue := params["queue"]
		_, hasNode := params["node"]
		if !hasNamespace || hasQueue || hasNode {
			return nil, fmt.Errorf("query placement: %w", ErrInvalidPlacementQuery)
		}
	}
	return params, nil
}

func queryStorageError(err error) error {
	return fmt.Errorf("query placements: %w: %w", ErrStorageUnavailable, err)
}

// Package service implements placement acceptance: the trial scheduling
// decision together with idempotent, conflict-aware registration. Accept is
// the single business entry point for a parsed placement request; it has no
// dependency on the HTTP transport.
package service

import (
	"context"
	"errors"
	"fmt"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
)

// Scheduling outcomes recorded on every placement.
const (
	StatusPlaced   = "placed"
	StatusRejected = "rejected"
	ReasonNoNode   = "no_eligible_node"
)

// Outcome classifies what Accept did with a submission.
type Outcome int

const (
	// Created means the (namespace, name) identity was registered for the
	// first time by this call.
	Created Outcome = iota
	// Identical means the identity already existed with the same request
	// content; the returned record is the original one.
	Identical
	// Conflict means the identity already existed with different content;
	// the returned record is the untouched original.
	Conflict
)

// ErrStorageUnavailable is the sentinel wrapped for every persistence failure.
var ErrStorageUnavailable = errors.New("storage unavailable")

// Service holds the collaborators needed to accept placements.
type Service struct {
	st *store.Store
}

// New builds the acceptance service over a store.
func New(st *store.Store) *Service {
	return &Service{st: st}
}

// Accept runs the trial placement and registers its result under the
// (namespace, name) identity. The first valid submission for an identity is
// stored and reported as Created; a later submission carrying the same request
// content is reported as Identical with the original record; one carrying
// different content is reported as Conflict and never changes the stored
// record. Scheduling results alone do not count as equal content. Input
// validation is expected to have happened before this call.
func (s *Service) Accept(ctx context.Context, p *store.Placement) (*store.Placement, Outcome, error) {
	// Fill omitted-field defaults through the single shared definition so
	// the trial, the stored record and the content comparison all see the
	// same input. The candidate array's order is left untouched.
	store.NormalizeInput(p)
	p.Status, p.Node, p.Reason = schedule(p)

	stored, created, err := s.st.Submit(ctx, p)
	if err != nil {
		return nil, Created, storageError(err)
	}
	if created {
		return stored, Created, nil
	}

	same, err := store.SameInput(p, stored)
	if err != nil {
		return nil, Created, storageError(err)
	}
	if !same {
		return stored, Conflict, nil
	}
	return stored, Identical, nil
}

func storageError(err error) error {
	return fmt.Errorf("accept placement: %w: %w", ErrStorageUnavailable, err)
}

