43		rec, outcome, err := svc.Accept(context.Background(), samplePlacement())
44		if err != nil {
45			t.Fatalf("accept: %v", err)
46		}
47		if outcome != Created {
48			t.Fatalf("outcome = %d, want Created", outcome)
49		}
50		if rec.Status != StatusPlaced || rec.Node == nil || *rec.Node != "node-a" || rec.Reason != nil {
51			t.Fatalf("decision not applied: %+v", rec)
